    &lt;/tr&gt;
  &lt;/thead&gt;
  &lt;tbody&gt;
    &lt;tr style="background:#f0f8f8;"&gt;
      &lt;td style="padding:0.4rem 0.8rem;"&gt;DB I&lt;/td&gt;
      ${cell(db1_rep)} ${cell(db1_fahr)} ${cell(db1_abo)} ${cell(db1_ges)}
    &lt;/tr&gt;
    &lt;tr&gt;
      &lt;td style="padding:0.4rem 0.8rem;"&gt;− Bereichsfixkosten&lt;/td&gt;
